-- ============================================================================
-- seed-demo.sql —— 演示数据种子（可视化段 D）
-- ⚠️ **本文件由 `scripts/seed-demo-gen.mjs` 生成，不要手改** —— 改生成器再重跑：
--       node scripts/seed-demo-gen.mjs
-- 生成日：2026-10-11（随机数种子 `20261011`，同一天重跑产物逐字相同）
-- ============================================================================
--
-- 【怎么跑】
--   1) 先确保 11 张表已有 `Source` 列：`mall_management_sql.sql` 末尾的 Migration 块
--      （2026-10-11「演示种子标记列」）。本文件**不复制那份 DDL** —— 建列只留一处，
--      跑本文件会先做一次前置检查；缺列时下面第一句 DELETE 会以 ERROR 1054 直接中止，
--      **不会写进半截数据**（这是故意的，不做静默兜底）。
--   2) mysql -h<host> -u<user> -p --default-character-set=utf8mb4 <db> < seed-demo.sql
--      ⚠️ 必须带库名（或 `USE`），否则 ERROR 1046；`--default-character-set=utf8mb4` 必给，
--         否则 Windows 控制台 GBK 会把中文写坏。
--   3) 最后打一次「全量重建」让统计表自洽：
--      POST /admin/stats/rebuild   （或管理端「经营数据 → 立即全量重建」）
--      ⚠️ `stats_daily` **不在本文件里**：它的行由 `StatsService.computeAndUpsert` 唯一写出，
--         那次 rebuild 会先 deleteAll 再从 `order` 重算 ⇒ 手写进去的会被抹掉。
--
-- 【幂等】每次执行先按 `Source = 'seed'` **先子后父**删掉上一次的种子行，再整批插入。
--   存量数据（`Source = ''`）一行不删、一行不改 —— 唯一的例外是下面那段
--   `login.CreateTime` 补值，它带 `WHERE CreateTime IS NULL` 守卫，同样可重复执行。
--   撤种子：`DELETE FROM `order_item` WHERE Source='seed'` …（照本文件删除段的顺序即可）
--
-- 【规模】49 天窗口；login 40 / user 40 / goods 44 / goods_audit 24 / order 222 / order_item 249 / cart 8 / notification 52 / admin_audit 60 / merchant_application 14
--
-- 【数据口径】
--   · 时间一律写成相对式 `DATE_SUB(CURDATE(), INTERVAL k DAY)`（k = 1..49）⇒ 任何时候执行
--     都落在「最近 49 天」，**永不出现未来日期**；精确到秒。
--   · 周末低谷 / 工作日高峰按**执行时的真实星期**过筛（`DAYOFWEEK(...) BETWEEN 2 AND 6`，
--     见 `order` / `order_item` 两条 INSERT 的 `WHERE`）—— 所以它不会随生成日漂移。
--     每天保底 1-2 单（趋势图**连续不跳日**），工作日再加 2-4 单。
--   · `order.Price` 是**这一单的小计**、`order.Quantity` 是**总件数**（同 `OrderService` 口径）；
--     `order_item.Subtotal` 逐行小计，`Σ Subtotal = order.Price` ⇒ 看板 GMV（`SUM(order.Price)`）
--     与明细自洽。
--   · 订单后续时间戳从「当天 00:00 到今天 00:00」的预算里**顺序扣**：扣不下就不走那一步、
--     状态自然降级 ⇒ 「最近两天的单多半还没发货」是算出来的，不是编的。
--   · `order.Id` / `goods.Id` 等自增列不写死，交给 AUTO_INCREMENT。
--   · 商品图 `https://picsum.photos/seed/<商品编码>/400` —— 联网可取，不占用仓库、不用真商品图。
--   · 演示口令**不入库**：`Password` 一律写占位符 `<demo-pwd>`（本仓不落明文口令）。
--     本地演示要登录时用 `DEMO_PWD=... node scripts/seed-demo-gen.mjs` 重新生成；上生产前必须改。
-- ============================================================================

-- ---- ⓪ 前置检查：11 张表都要有 `Source` 列（期望输出 11/11）----
SELECT CONCAT('seed 前置检查：Source 列 ', COUNT(*), '/11 张表就位') AS `seed_precheck`
  FROM information_schema.COLUMNS
 WHERE TABLE_SCHEMA = DATABASE() AND COLUMN_NAME = 'Source'
   AND TABLE_NAME IN ('login','user','goods','goods_audit','order','order_item','cart',
                      'notification','admin_audit','merchant_application','stats_daily');

-- ---- ① 清上一次的种子行（**先子后父**；存量行 Source='' 一律不动）----
DELETE FROM `order_item`           WHERE `Source` = 'seed';
DELETE FROM `order`                WHERE `Source` = 'seed';
DELETE FROM `cart`                 WHERE `Source` = 'seed';
DELETE FROM `notification`         WHERE `Source` = 'seed';
DELETE FROM `admin_audit`          WHERE `Source` = 'seed';
DELETE FROM `goods_audit`          WHERE `Source` = 'seed';
DELETE FROM `merchant_application` WHERE `Source` = 'seed';
DELETE FROM `goods`                WHERE `Source` = 'seed';
DELETE FROM `user`                 WHERE `Source` = 'seed';
DELETE FROM `login`                WHERE `Source` = 'seed';

-- ---- ② 存量账号补 `CreateTime`（用户要求的「login 补 CreateTime」）----
-- 存量 9 行里有 7 行 `CreateTime` 为空 ⇒ 它们在「用户增长」图上没有日期、画不出来。
-- ⚠️ 守卫是 `AND CreateTime IS NULL`：补过一次就不再命中 ⇒ **本段可重复执行**。
-- ⚠️ 刻意跳过 `i2probe`：那是本轮之前探针脚本留下的账号，不是演示数据（已在交付说明里单列）。
UPDATE `login` SET `CreateTime` = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 44 DAY), INTERVAL 34121 SECOND) WHERE `UserName` = '1' AND `CreateTime` IS NULL;
UPDATE `login` SET `CreateTime` = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 41 DAY), INTERVAL 45123 SECOND) WHERE `UserName` = '1111' AND `CreateTime` IS NULL;
UPDATE `login` SET `CreateTime` = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 38 DAY), INTERVAL 51234 SECOND) WHERE `UserName` = '123' AND `CreateTime` IS NULL;
UPDATE `login` SET `CreateTime` = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 43 DAY), INTERVAL 39777 SECOND) WHERE `UserName` = '2222' AND `CreateTime` IS NULL;
UPDATE `login` SET `CreateTime` = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 35 DAY), INTERVAL 60321 SECOND) WHERE `UserName` = 'aaa' AND `CreateTime` IS NULL;
UPDATE `login` SET `CreateTime` = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 48 DAY), INTERVAL 28800 SECOND) WHERE `UserName` = 'admin' AND `CreateTime` IS NULL;
UPDATE `login` SET `CreateTime` = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 36 DAY), INTERVAL 55012 SECOND) WHERE `UserName` = '性暗示' AND `CreateTime` IS NULL;

