-- ---- ⑦ `order`：~222 单，全状态覆盖 + 49 天长跨度 ----
-- `WHERE` 是本文件唯一「按执行日算」的地方：`gate=1` 的行只在**工作日**落入（周末低谷）。
-- `gate=0` 的行每天都落 ⇒ 趋势图连续不跳日。
INSERT INTO `order`
  (`MerchantId`,`CustomerId`,`OrderId`,`Price`,`ProductInformation`,`Images`,`PayIf`,`DeliveryIf`,`ReceiveIf`,
   `CreateTime`,`SettlementDate`,`Quantity`,`TradeNo`,`PaymentMethod`,`PaidAt`,`ExpressCompany`,`TrackingNo`,`ShippedAt`,`ReceivedAt`,`CancelledAt`,`Source`)
SELECT v.mid, v.cid, v.oid, v.price, v.pinfo, v.imgs, v.payif, v.dlyif, v.rcvif,
       DATE_FORMAT(DATE_ADD(DATE_SUB(CURDATE(), INTERVAL v.k DAY), INTERVAL v.sec SECOND), '%Y-%m-%d %H:%i:%s'),
       IF(v.settleoff = 0, NULL, DATE_FORMAT(DATE_ADD(DATE_SUB(CURDATE(), INTERVAL v.k DAY), INTERVAL v.settleoff SECOND), '%Y-%m-%d %H:%i:%s')),
       v.qty,
       IF(v.trade = '', NULL, CONCAT('PAY', DATE_FORMAT(DATE_ADD(DATE_SUB(CURDATE(), INTERVAL v.k DAY), INTERVAL v.payoff SECOND), '%Y%m%d'), v.trade)),
       NULLIF(v.pm, ''),
       IF(v.payoff   = 0, NULL, DATE_ADD(DATE_SUB(CURDATE(), INTERVAL v.k DAY), INTERVAL v.payoff SECOND)),
       NULLIF(v.shipco, ''), NULLIF(v.track, ''),
       IF(v.shipoff  = 0, NULL, DATE_ADD(DATE_SUB(CURDATE(), INTERVAL v.k DAY), INTERVAL v.shipoff SECOND)),
       IF(v.rcvoff   = 0, NULL, DATE_ADD(DATE_SUB(CURDATE(), INTERVAL v.k DAY), INTERVAL v.rcvoff SECOND)),
       IF(v.canceloff = 0, NULL, DATE_ADD(DATE_SUB(CURDATE(), INTERVAL v.k DAY), INTERVAL v.canceloff SECOND)),
