-- ---- ⑬ 收尾：让统计表自洽 ----
-- `stats_daily` 不在这里写（见文件头）。灌完本文件后**必须**打一次全量重建：
--     POST /admin/stats/rebuild
-- 或管理端「经营数据 → 立即全量重建」。重建会先清空 `stats_daily`、再从上面的 `order`
-- 全量重算 ⇒ 看板的 GMV / 成单数 / 买家数与你刚灌的订单一一对应。

-- ---- 自检（可选，跑完看一眼）----
SELECT 'login' AS `table`, COUNT(*) AS `seed_rows` FROM `login` WHERE `Source`='seed'
UNION ALL SELECT 'user', COUNT(*) FROM `user` WHERE `Source`='seed'
UNION ALL SELECT 'goods', COUNT(*) FROM `goods` WHERE `Source`='seed'
UNION ALL SELECT 'goods_audit', COUNT(*) FROM `goods_audit` WHERE `Source`='seed'
UNION ALL SELECT 'order', COUNT(*) FROM `order` WHERE `Source`='seed'
UNION ALL SELECT 'order_item', COUNT(*) FROM `order_item` WHERE `Source`='seed'
UNION ALL SELECT 'cart', COUNT(*) FROM `cart` WHERE `Source`='seed'
UNION ALL SELECT 'notification', COUNT(*) FROM `notification` WHERE `Source`='seed'
UNION ALL SELECT 'admin_audit', COUNT(*) FROM `admin_audit` WHERE `Source`='seed'
UNION ALL SELECT 'merchant_application', COUNT(*) FROM `merchant_application` WHERE `Source`='seed'
UNION ALL SELECT 'orders_done', COUNT(*) FROM `order` WHERE `Source`='seed' AND `PayIf`=1 AND `DeliveryIf`=1 AND `ReceiveIf`=1
UNION ALL SELECT 'orders_unpaid', COUNT(*) FROM `order` WHERE `Source`='seed' AND `PayIf`=0 AND `DeliveryIf`=0 AND `ReceiveIf`=0 AND `CancelledAt` IS NULL
UNION ALL SELECT 'orders_cancelled', COUNT(*) FROM `order` WHERE `Source`='seed' AND `CancelledAt` IS NOT NULL
UNION ALL SELECT 'order_span_days', COUNT(DISTINCT DATE(`CreateTime`)) FROM `order` WHERE `Source`='seed';
